    /// <summary>
    /// Single player card in the side columns (CSS <c>.pcard</c>): jersey number plate, name +
    /// <c>#id</c> + status chip, HP, telemetry and five actions (POV · ÖLÇ · takım · SIFIRLA · AT).
    /// <para>
    /// <b>Look comes from the prefab</b> (<c>Assets/_Shared/App/Resources/UI/AdminPlayerRow.prefab</c>,
    /// generated by <c>GirdapUiBuilder.BuildPlayerRow</c>); this class is behaviour only. Unbound
    /// fields silently draw nothing — keep prefab wiring intact.
    /// </para>
    /// <para>Kick is two-step (<see cref="ConfirmSeconds"/>): taking a player out of the fight must
    /// not happen on one stray click.</para>
    /// <para>⚠️ SIFIRLA is the SAME command and grammar as the stats row's (<see cref="HoldButton"/>):
    /// a tap voids the alignment and keeps the saved anchor, a 1 s hold wipes that anchor too. One
    /// button, two screens — never a different meaning per screen. Reload (KALİBRE) stays in the
    /// stats panel only.</para>
    /// </summary>
    public class AdminPlayerRow : MonoBehaviour
    {
        /// <summary>Card height <b>fallback</b> (px, CSS <c>.pcard</c>); real height is read from the
        /// prefab's <see cref="RectTransform"/> (<see cref="AdminHud"/>) so resizing it in the prefab
        /// reflows the column.</summary>
        public const float Height = 136f;

